package com.watchdrift

import com.watchdrift.core.Stats
import com.watchdrift.data.AppData
import com.watchdrift.data.parseAppData
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Verifies the Kotlin statistics engine reproduces the Python engine's output
 * on the REAL data file, not on synthetic inputs.
 *
 * reference.json was generated by running watch_drift.py's own functions over
 * watch_drift.json. If a change here alters a rate, a segment boundary, or an
 * error bar, this test fails — which is the whole point of having it. Six
 * watches, 59 readings, spanning single-segment, multi-segment, and
 * too-young-to-fit cases.
 */
class StatsTest {

    private val tol = 1e-6

    private fun resource(name: String): String =
        javaClass.classLoader!!.getResourceAsStream(name)!!
            .bufferedReader().use { it.readText() }

    private val data: AppData by lazy { parseAppData(resource("watch_drift.json")) }
    private val reference: JSONObject by lazy { JSONObject(resource("reference.json")) }

    @Test
    fun `data file parses with all readings intact`() {
        assertEquals(6, data.watches.size)
        assertEquals(59, data.readings.size)
    }

    @Test
    fun `raw deviation matches python for every second of the minute`() {
        val arr = reference.getJSONArray("rawDeviation")
        for (i in 0 until arr.length()) {
            val o = arr.getJSONObject(i)
            assertEquals(
                "raw_deviation(${o.getInt("s")})",
                o.getInt("dev"),
                Stats.rawDeviation(o.getInt("s"))
            )
        }
    }

    @Test
    fun `minute adjust shifts total by whole minutes`() {
        assertEquals(90, Stats.totalDeviation(30, 1))
        assertEquals(-61, Stats.totalDeviation(59, -1))
        assertEquals(0, Stats.totalDeviation(0, 0))
    }

    @Test
    fun `min window days matches python`() {
        val arr = reference.getJSONArray("minWindow")
        for (i in 0 until arr.length()) {
            val o = arr.getJSONObject(i)
            assertEquals(
                "min_window_days(${o.getDouble("rate")})",
                o.getDouble("days"),
                Stats.minWindowDays(o.getDouble("rate")),
                tol
            )
        }
    }

    @Test
    fun `every watch reproduces the python fit exactly`() {
        val arr = reference.getJSONArray("watches")
        assertTrue("reference has watches", arr.length() > 0)

        for (i in 0 until arr.length()) {
            val exp = arr.getJSONObject(i)
            val id = exp.getString("id")
            val name = exp.getString("name")
            val rs = data.readingsFor(id)

            assertEquals("$name: reading count", exp.getInt("n"), rs.size)

            val info = Stats.watchRateInfo(rs)

            // Segmentation is the part most likely to drift on a port: it is
            // path-dependent, refitting after every appended reading.
            assertEquals("$name: segment count", exp.getInt("nSegments"), info.segs.size)
            val expSizes = exp.getJSONArray("segSizes")
            for (j in 0 until expSizes.length()) {
                assertEquals(
                    "$name: size of segment $j",
                    expSizes.getInt(j),
                    info.segs[j].size
                )
            }

            assertEquals(
                "$name: current segment span",
                exp.getDouble("segSpanDays"),
                Stats.segSpanDays(info.seg),
                tol
            )

            assertEqualsNullable("$name: rate", exp, "rateSPerDay", info.rate)
            assertEquals("$name: collecting", exp.getBoolean("collecting"), info.collecting)
            assertEquals("$name: source", exp.getString("source"), info.source)
            assertEqualsNullable("$name: needDays", exp, "needDays", info.needDays)
            assertEqualsNullable("$name: lifetime", exp, "lifetime", info.life)

            val fit = Stats.lsqFit(info.seg)
            if (exp.isNull("fitSlope")) {
                assertNull("$name: expected no fit", fit)
            } else {
                assertNotNull("$name: expected a fit", fit)
                assertEquals("$name: slope", exp.getDouble("fitSlope"), fit!!.slope, tol)
                assertEquals(
                    "$name: intercept",
                    exp.getDouble("fitIntercept"), fit.intercept, 1e-4
                )
                assertEquals(
                    "$name: slope stderr",
                    exp.getDouble("fitStderr"), fit.slopeStderr, tol
                )
            }

            assertEquals("$name: readErr", exp.getDouble("readErr"), Stats.readErr(info.seg), tol)

            assertEqualsNullable(
                "$name: predict at last", exp, "predictAtLast",
                Stats.predictOffset(rs, rs.last().ts)
            )
        }
    }

    @Test
    fun `citizen pro segments split at the sync, not at the minute adjustments`() {
        // This watch has both a postSync reset and several ADJ rows. ADJ rows
        // must NOT break a segment: totalOffsetSec is continuous through a
        // minute correction, so splitting there would halve the span and
        // double the error bar for no reason.
        val rs = data.readingsFor("1774645751181")
        val segs = Stats.segmentReadings(rs)
        assertEquals(2, segs.size)
        assertTrue("second segment starts at the sync", segs[1].first().postSync)
    }

    @Test
    fun `a two point fit uses read error as the noise floor`() {
        // With 2 points there are no spare degrees of freedom, so scatter
        // cannot be estimated from the data. Claiming a tiny error bar there
        // would be false precision.
        val rs = data.readingsFor("1774645751181").take(2)
        val fit = Stats.lsqFit(rs)
        assertNotNull(fit)
        assertTrue("stderr is positive", fit!!.slopeStderr > 0)
    }

    @Test
    fun `fewer than two readings yields no rate`() {
        val rs = data.readingsFor("1774645751181").take(1)
        val info = Stats.watchRateInfo(rs)
        assertNull(info.rate)
        assertTrue(info.collecting)
        assertEquals("none", info.source)
    }

    @Test
    fun `zero span returns no fit`() {
        val rs = data.readingsFor("1774645751181").take(1)
        assertNull(Stats.lsqFit(rs + rs))
    }

    private fun assertEqualsNullable(
        msg: String, exp: JSONObject, key: String, actual: Double?
    ) {
        if (exp.isNull(key)) {
            assertNull("$msg: expected null", actual)
        } else {
            assertNotNull("$msg: expected a value", actual)
            assertEquals(msg, exp.getDouble(key), actual!!, tol)
        }
    }
}
